			if frame>0 and frame%2==0:
				if legacy: game.GameLoop.physics_process(game,1.0/30.0); Pose.reset(game)
				else: game._physics_process(1.0/30.0)
			if not legacy: Pose.present(game,(frame%2)*0.5)
